Local Notation FAM := fam_0RB1LA_1RC1RD_1LD1RB_1RC0LA.

(** ** The ladder, as DATA

    0 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_0RB1LA_1RC1RD_1LD1RB_1RC0LA : list (LRule * list rstep) :=
  [].
Local Notation lad := lad_0RB1LA_1RC1RD_1LD1RB_1RC0LA.

Definition rules_0RB1LA_1RC1RD_1LD1RB_1RC0LA : list LRule := map fst lad.
Local Notation rules := rules_0RB1LA_1RC1RD_1LD1RB_1RC0LA.

Lemma ladder_ok_0RB1LA_1RC1RD_1LD1RB_1RC0LA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1LA_1RC1RD_1LD1RB_1RC0LA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1LA_1RC1RD_1LD1RB_1RC0LA. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(** ** What this board establishes

    0 of 0 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 0 of them
    collapse to 5 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    0 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_0RB1LA_1RC1RD_1LD1RB_1RC0LA : list (LRule * list rstep) :=
  [].
Definition nrules_0RB1LA_1RC1RD_1LD1RB_1RC0LA : list LRule := map fst nlad_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
Local Notation nrules := nrules_0RB1LA_1RC1RD_1LD1RB_1RC0LA.

Lemma nladder_ok_0RB1LA_1RC1RD_1LD1RB_1RC0LA : check_ladder tm [] nlad_0RB1LA_1RC1RD_1LD1RB_1RC0LA = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_0RB1LA_1RC1RD_1LD1RB_1RC0LA : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_0RB1LA_1RC1RD_1LD1RB_1RC0LA. Qed.

Definition iarm0_0_0RB1LA_1RC1RD_1LD1RB_1RC0LA : LRule :=
  mkLRule (mkC StD (mkS [S1] [] 0 0 []) S0 (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]))
          (mkC StD (mkS [S1] [] 0 0 []) S0 (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0])) 0 1.
