Lemma bootl_0RB1LA_1RC1RD_1LD1RB_1RC0LA :
  stepn tm 40 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm 40 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 40 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_0RB1LA_1RC1RD_1LD1RB_1RC0LA : NeverQuasiHaltsTr tm_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
Proof.
  eapply (boardN_neverqhtr tm_0RB1LA_1RC1RD_1LD1RB_1RC0LA pins_0RB1LA_1RC1RD_1LD1RB_1RC0LA FAM 4
                           iarm_0RB1LA_1RC1RD_1LD1RB_1RC0LA 0 1
                           farm_0RB1LA_1RC1RD_1LD1RB_1RC0LA 1 1
                           fm1_0RB1LA_1RC1RD_1LD1RB_1RC0LA fm2_0RB1LA_1RC1RD_1LD1RB_1RC0LA 0
                           nrules vsegs_0RB1LA_1RC1RD_1LD1RB_1RC0LA vis_0RB1LA_1RC1RD_1LD1RB_1RC0LA
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 2; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 3; vm_compute; reflexivity. }
    destruct ph as [|ph].
    { exists 1; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_reach_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
  - exact iarm_lhs_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
  - exact iarm_rhs_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
  - lia.
  - lia.
  - exact farm_reach_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
  - exact farm_lhs_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
  - exact farm_rhs_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
  - exact nrules_sound_0RB1LA_1RC1RD_1LD1RB_1RC0LA.
